let canvasSize = 1200;
//let COLORS = ["rgb(255, 25, 25)","#6cff27","#1525ff","#ff25e3","#25fff7","#ffb625","#ff2525","#6cff27","#1525ff",];
let COLORS = ["#000845","#00098a","#5567a9","#4f46d2","#3ba3da","#5989d0","#03659a","#13e6f1","#96d5f7","#d8f6ff"];

let scale = [130.81, 146.83, 164.81, 196.00, 220.00, 261.63, 293.66, 329.63, 392.00, 440.00];
let oldestNote; 
let notes = [];
//let osc;
let hitArea = 20;
let noteSize = 20;
let maxhitArea = 250;
let minhitArea = 20;
let synth;
let maxspeed = 2;
let players = [];

function setup() {
  createCanvas(canvasSize, canvasSize);

  //osc = new p5.Oscillator('sine')
  synth = new p5.PolySynth();

  for(let i = 0; i < 100; i++){
    let n = new note();
    n.position.x = random(0,canvasSize);
    n.position.y = random(0,canvasSize);
    n.vec.x = random(-maxspeed,maxspeed);
    n.vec.y = random(-maxspeed,maxspeed);
    notes.push(n);
  }

}



function draw() {
  background("#00014f3f");

  for(let i = 0; i < notes.length; i++){
    notes[i].draw();
    for(let j = 0; j < players.length; j++){
      if(dist(players[j].x,players[j].y,notes[i].position.x,notes[i].position.y) < players[j].hitarea){
        notes[i].hit(players[j].x,players[j].y,players[j].hitarea);
      }
    }
    //notes[i].hit((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  }

  noFill();
  stroke(255);
  for(let i = 0; i < players.length; i++){
    players[i].draw();
  }
  players = players.filter(p => p.hitarea < maxhitArea);

  //circle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),hitArea*2);
  //itArea += 1;
  //if(hitArea > maxhitArea){
    //hitArea = minhitArea;
  //}

  if(players.length == 0){
    for(let i = 0; i < notes.length; i++){
      notes[i].ishitting = false;
    }
  }

}

function mousePressed(){
  players.push(new player((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

 function note(){
  this.note;
  this.position = {x:0,y:0};
  this.vec = {x:0,y:0};
  this.ishitting = false;

  let idx = floor(random(scale.length));
  this.frecuency = scale[idx];
  this.color = color(COLORS[idx]);
  this.color.setAlpha(150);
  this.playing = 0;

  this.draw = function(){
    fill(this.color);
    noStroke();
    circle(this.position.x,this.position.y,noteSize);

    if(this.playing > 0){
      this.playing--;
      blendMode(ADD);
      fill(red(this.color), green(this.color), blue(this.color), 200);
      circle(this.position.x,this.position.y,noteSize*1.2);
      blendMode(BLEND);

    }

    if(this.position.x > canvasSize || this.position.x < 0){
      this.vec.x *= -1;
    }
    if(this.position.y > canvasSize || this.position.y < 0){
      this.vec.y *= -1;
    }
    this.position.x += this.vec.x;
    this.position.y += this.vec.y;
  } 

  this.hit = function(mx,my,mhitarea){
    if(!this.ishitting && dist(mx,my,this.position.x,this.position.y) < mhitarea*0.6){
      this.vec.x *= -1;
      this.vec.y *= -1;
      this.ishitting = true;
      this.playing = 10;
      this.play();
    }
    if(this.ishitting && dist(mx,my,this.position.x,this.position.y) > mhitarea*0.6){
      this.ishitting = false;
    }
  }

  this.play = function(){
    //play sound
    /*
    osc.start();
    osc.freq(this.frecuency);
      osc.amp(0.5,0.1);
      osc.amp(0,0.5);
      */
    synth.play(
      this.frecuency,
      0.1,   // 音量
      0,     // delay
      0.1    // duration
    );
  }
 }

 function player(x,y){
  this.x = x;
  this.y = y;
  this.hitarea = minhitArea;

  this.draw = function(){
    this.hitarea += 1;
    circle(this.x,this.y,this.hitarea);
  }

 }

